function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 100 - pick(3) : 1 + pick(8);
  const style = pick(5);
  let nums;
  if (style === 0) {
    nums = Array.from({ length: n }, () => 1 + pick(30));
  } else if (style === 1) {
    // Every value shares a factor g, except sometimes one outlier that is worth removing.
    const g = 2 + pick(5);
    nums = Array.from({ length: n }, () => g * (1 + pick(Math.floor(30 / g))));
    if (rand() < 0.6) nums[pick(n)] = 1 + pick(30);
  } else if (style === 2) {
    const chains = [[1, 2, 4, 8, 16], [1, 3, 9, 27], [1, 5, 25], [2, 6, 18], [5, 10, 20]];
    const chain = chains[pick(chains.length)];
    nums = Array.from({ length: n }, () => chain[pick(chain.length)]);
  } else if (style === 3) {
    nums = new Array(n).fill(1 + pick(30));
  } else {
    const pool = Array.from({ length: 1 + pick(3) }, () => 1 + pick(30));
    nums = Array.from({ length: n }, () => pool[pick(pool.length)]);
  }
  return [nums];
}
